{
  "id": 37,
  "knowledge": "Health System Capacity Index (HSCI)",
  "description": "Measures the disaster area's health system ability to handle medical emergencies",
  "definition": "HSCI = PHRS \\times medcap\\_numeric \\times \\left(1 - \\frac{hazlevel\\_numeric}{6}\\right), \\text{ where medcap\\_numeric maps Adequate=1.0, Limited=0.6, Critical=0.3, else=0 for medical emergency capacity, and hazlevel\\_numeric represents severity level from 1-5}"
}

{
  "id": 26,
  "knowledge": "Public Health Emergency",
  "description": "Identifies situations with severe public health implications",
  "definition": "Conditions where diseaserisk is 'High' AND waterqualityindex < 50 AND PHRS < 40, indicating critical threats to public health requiring immediate intervention"
}

{
  "id": 44,
  "knowledge": "Critical Health Response Requirement",
  "description": "Identifies areas needing urgent health system reinforcement",
  "definition": "Areas experiencing Public Health Emergency where HSCI < 30 AND staffingProfile.readiness.ppe_status is 'Critical', indicating severely compromised health response capacity requiring immediate intervention"
}

{
  "id": 0,
  "knowledge": "hazlevel",
  "description": "Illustrates the severity classification of disaster events",
  "definition": "Level 1 represents minimal threat, Level 2 indicates moderate danger, Level 3 shows significant hazard, Level 4 denotes severe emergency situation, and Level 5 signifies catastrophic conditions requiring maximum response"
}

{
  "id": 34,
  "knowledge": "Staffing to Need Ratio (SNR)",
  "description": "Evaluates whether staffing levels match operational requirements",
  "definition": "SNR = \\frac{staffingprofile->>'personnel'->>'total'}{(impactMetrics->>'population'->>'affected'/10000)} \\times PER \\times ppe\\_factor, \\text{ where ppe\\_factor is 1.2 for Adequate, 0.8 for Limited, 0.5 for Critical PPE status, and 0 for else}"
}

{
  "id": 28,
  "knowledge": "Community Resilience Builder",
  "description": "Identifies operations that strengthen local community capacity",
  "definition": "Operations where localcapacitygrowth is 'Active' AND commengagelvl is 'High' AND BSI > 70, representing efforts that effectively build sustainable community resilience"
}

{
  "id": 52,
  "knowledge": "Community Resilience Classification",
  "description": "Categorizes operations based on their community engagement and resilience-building effectiveness",
  "definition": "Operations satisfying criteria from Community Resilience Builder are classified as Community Resilience Builder; operations meeting criteria from Community Resilience Opportunity are classified as Community Resilience Opportunity; all other operations are classified as Standard Operation"
}

{
  "id": 51,
  "knowledge": "Environmental Impact Classification",
  "description": "Categorizes operations based on their Environmental Impact Factor (EIF) values",
  "definition": "Sustainable (EIF < 50) indicates operations with minimal environmental footprint and strong sustainability practices; Moderate Impact (50 \u2264 EIF < 100) represents operations with reasonable environmental management; High Impact (EIF \u2265 100) indicates operations with significant environmental footprint requiring mitigation strategies"
}

{
  "id": 16,
  "knowledge": "Environmental Impact Factor (EIF)",
  "description": "Quantifies the environmental footprint of disaster response operations",
  "definition": "EIF = carbontons \\times \\left(1 - \\frac{renewenergypct}{100}\\right) + (100 - recyclepct) \\times 0.5"
}
